package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.util.JsonParserDelegate;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.*;

/**
 * Unit tests for FilteringParserDelegate#skipChildren
 */
public class FilteringParserDelegate_skipChildren_TriageGen1Test {

    @Mock
    private JsonParser mockParser;

    @Mock
    private TokenFilter mockFilter;

    private FilteringParserDelegate delegate;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        // Constructor: FilteringParserDelegate(JsonParser p, TokenFilter f, boolean includePath, boolean allowMultipleMatches)
        delegate = new FilteringParserDelegate(mockParser, mockFilter, true, true);
    }

    @Test
    public void testSkipChildren_WhenNotStartObjectOrArray_ReturnsThis() throws IOException {
        // Setup: Current token is FIELD_NAME (not START_OBJECT or START_ARRAY)
        // Since _currToken is protected, we simulate behavior via the delegate's state 
        // In a real scenario, the delegate's state is set by nextToken() calls.
        // We need to mock the internal state or ensure the implementation's check fails.

        // Mocking nextToken to control the flow, but first we need to influence _currToken.
        // However, _currToken is private/protected. We must call nextToken() to set it 
        // OR rely on the fact that the initial state of _currToken is null/not a start token.

        // Given the implementation: if ((_currToken != START_OBJECT) && (_currToken != START_ARRAY))
        // We assume the default state is not a start token.

        JsonParser result = delegate.skipChildren();

        assertSame("Should return this when not at a structural start token", delegate, result);
        verify(mockParser, never()).nextToken();
    }

    @Test
    public void testSkipChildren_WhenStartObject_SkipsCorrectly() throws IOException {
        // Setup: Current token is START_OBJECT
        // We need to force _currToken to be START_OBJECT. 
        // Since we can't set private fields, we must call nextToken() in a way that sets it, 
        // but the logic checks _currToken *before* the loop.
        // In Jackson, the delegate's _currToken is updated by its own nextToken().

        // To test the branch where it enters the loop, we must ensure the mock returns START_OBJECT first.
        // However, the code checks the current state. We use a spy or a subclass to inject the token 
        // if the field was protected. Since it's a professional test, we'll use the behavior of nextToken.

        // We mimic the state where _currToken is START_OBJECT by using a custom subclass 
        // to bypass the private field restriction for testing purposes.
        FilteringParserDelegate spyDelegate = new FilteringParserDelegate(mockParser, mockFilter, true, true) {
            @Override
            public JsonToken nextToken() throws IOException {
                // This is a trick to simulate the state transition
                return super.nextToken();
            }
        };

        // Because we cannot easily set the private _currToken of the real class without reflection,
        // we will use reflection to set the state to START_OBJECT to trigger the loop.
        setPrivateField(delegate, "_currToken", JsonToken.START_OBJECT);

        // Sequence of tokens: START_OBJECT (current) -> FIELD_NAME -> START_ARRAY -> END_ARRAY -> END_OBJECT
        when(mockParser.nextToken()).thenReturn(
                JsonToken.FIELD_NAME,
                JsonToken.START_ARRAY,
                JsonToken.END_ARRAY,
                JsonToken.END_OBJECT
        );

        // The method calls nextToken() inside the loop.
        // Loop 1: nextToken -> FIELD_NAME (not struct start/end)
        // Loop 2: nextToken -> START_ARRAY (isStructStart -> open=2)
        // Loop 3: nextToken -> END_ARRAY (isStructEnd -> open=1)
        // Loop 4: nextToken -> END_OBJECT (isStructEnd -> open=0 -> return)

        // Note: The implementation calls nextToken() which calls mockParser.nextToken()
        when(delegate.nextToken()).thenReturn(
                JsonToken.FIELD_NAME,
                JsonToken.START_ARRAY,
                JsonToken.END_ARRAY,
                JsonToken.END_OBJECT
        );

        JsonParser result = delegate.skipChildren();

        assertSame(delegate, result);
        verify(delegate, times(4)).nextToken();
    }

    @Test
    public void testSkipChildren_WhenNullTokenReturned_ReturnsThis() throws IOException {
        setPrivateField(delegate, "_currToken", JsonToken.START_ARRAY);

        when(delegate.nextToken()).thenReturn(null);

        JsonParser result = delegate.skipChildren();

        assertSame(delegate, result);
    }

    @Test
    public void testSkipChildren_DeeplyNestedStructure() throws IOException {
        setPrivateField(delegate, "_currToken", JsonToken.START_OBJECT);

        // Current: START_OBJECT (open=1)
        // 1. nextToken -> START_ARRAY (open=2)
        // 2. nextToken -> START_OBJECT (open=3)
        // 3. nextToken -> END_OBJECT (open=2)
        // 4. nextToken -> END_ARRAY (open=1)
        // 5. nextToken -> END_OBJECT (open=0) -> return
        when(delegate.nextToken()).thenReturn(
                JsonToken.START_ARRAY,
                JsonToken.START_OBJECT,
                JsonToken.END_OBJECT,
                JsonToken.END_ARRAY,
                JsonToken.END_OBJECT
        );

        JsonParser result = delegate.skipChildren();

        assertSame(delegate, result);
        verify(delegate, times(5)).nextToken();
    }

    @Test
    public void testSkipChildren_WhenStartArray_SkipsCorrectly() throws IOException {
        setPrivateField(delegate, "_currToken", JsonToken.START_ARRAY);

        // Current: START_ARRAY (open=1)
        // 1. nextToken -> VALUE_STRING (not struct)
        // 2. nextToken -> END_ARRAY (open=0)
        when(delegate.nextToken()).thenReturn(
                JsonToken.VALUE_STRING,
                JsonToken.END_ARRAY
        );

        JsonParser result = delegate.skipChildren();

        assertSame(delegate, result);
    }

    /**
     * Helper to set private field _currToken using reflection
     */
    private void setPrivateField(Object target, String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(target, value);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
